CREATE PROCEDURE PRC_REGISTRA_PAGAMENTO (IN P_ID_RATA INTEGER, IN P_IMPORTO DECIMAL(12,2))
BEGIN
  UPDATE PRT_PAGAMENTO
  SET ESITO = 'CONTABILIZZATO'
  WHERE ID_RATA = P_ID_RATA;

  UPDATE PRT_RATA
  SET STATO = 'PAGATA'
  WHERE ID_RATA = P_ID_RATA;
END;

